<template>
  <Modal ref="modal" @hidden="$refs.form && $refs.form.reset()">
    <h2 class="box__title">
      {{ $t('editUserModal.edit', { username: user.username }) }}
    </h2>
    <Error :error="error"></Error>
    <UserForm
      ref="form"
      :user="user"
      :loading="loading"
      :default-values="user"
      @submitted="editUser"
      @remove-two-factor-auth="$refs.disableTwoFactorAuthModal.show()"
    >
      <div class="align-left">
        <a
          class="user-admin-edit__delete"
          @click="$refs.deleteUserModal.show()"
        >
          {{ $t('editUserModal.delete') }}
        </a>
      </div>
    </UserForm>
    <DeleteUserModal
      ref="deleteUserModal"
      :user="user"
      @delete-user="$emit('delete-user', $event)"
    ></DeleteUserModal>
    <DisableTwoFactorAuthModal
      ref="disableTwoFactorAuthModal"
      :user="user"
      @two-factor-auth-disabled="onTwoFactorAuthDisabled"
    ></DisableTwoFactorAuthModal>
  </Modal>
</template>

<script>
import modal from '@baserow/modules/core/mixins/modal'
import error from '@baserow/modules/core/mixins/error'
import UserAdminService from '@baserow/modules/core/services/admin/users'
import UserForm from '@baserow/modules/core/components/admin/users/forms/UserForm'
import DeleteUserModal from '@baserow/modules/core/components/admin/users/modals/DeleteUserModal'
import DisableTwoFactorAuthModal from '@baserow/modules/core/components/admin/users/modals/DisableTwoFactorAuthModal'

export default {
  name: 'EditUserModal',
  components: { DeleteUserModal, DisableTwoFactorAuthModal, UserForm },
  mixins: [modal, error],
  props: {
    user: {
      type: Object,
      required: true,
    },
  },
  emits: ['delete-user', 'update'],
  data() {
    return {
      loading: false,
    }
  },
  methods: {
    async editUser(values) {
      this.loading = true
      this.hideError()

      try {
        const { data: userData } = await UserAdminService(this.$client).update(
          this.user.id,
          values
        )
        this.$emit('update', userData)
        this.loading = false
        this.hide()
      } catch (error) {
        this.loading = false
        this.handleError(error, 'application')
      }
    },
    onTwoFactorAuthDisabled() {
      this.$emit('update', { ...this.user, two_factor_auth: null })
    },
  },
}
</script>
